      }
    },
    "constants": {
      "addressAsNull": "0x0000000000000000000000000000000000000000"
    }
  },
  "display": {
    "formats": {
      "setup(address[] _owners, uint256 _threshold, address to, bytes data, address fallbackHandler, address paymentToken, uint256 payment, address paymentReceiver)": {
        "$id": "setup",
        "intent": "Setup Safe",
        "fields": [
          {
            "path": "_owners.[]",
            "label": "Signer",
            "format": "addressName",
            "params": {
              "types": [
                "eoa",
                "wallet"
              ]
            }
          },
          {
            "path": "_threshold",
            "label": "Threshold",
            "format": "raw",
            "visible": "always"
          },
          {
            "path": "fallbackHandler",
            "label": "Fallback handler",
            "format": "addressName",
            "params": {
              "types": [
                "contract"
              ]
            },
            "visible": "always"
          },
          {
            "path": "payment",
            "label": "Payment",
            "format": "tokenAmount",
            "params": {
              "tokenPath": "paymentToken",
              "nativeCurrencyAddress": "$.metadata.constants.addressAsNull"
            },
            "visible": { "ifNotIn": [0, "0"] }
          },
          {
            "path": "paymentReceiver",
            "label": "Payment receiver",
            "format": "addressName",
            "params": {
              "types": [
                "eoa",
                "wallet",
                "contract"
              ]
            },
            "visible": { "ifNotIn": ["0x0000000000000000000000000000000000000000"] }
          },
          {
            "path": "to",
            "label": "Delegate call to",
            "format": "addressName",
            "params": {
              "types": [
                "contract"
              ]
            },
            "visible": { "ifNotIn": ["0x0000000000000000000000000000000000000000"] }
          },
          {
            "path": "data",
            "label": "Setup delegate call",
            "format": "calldata",
            "params": {
              "calleePath": "to"
            },
            "visible": "always"
          }
        ]
      },
      "execTransaction(address to, uint256 value, bytes data, uint8 operation, uint256 safeTxGas, uint256 baseGas, uint256 gasPrice, address gasToken, address refundReceiver, bytes signatures)": {
        "$id": "execTransaction",
        "intent": "sign multisig operation",
        "fields": [
          {
            "path": "operation",
            "label": "Operation type",
            "format": "enum",
            "params": {
              "$ref": "$.metadata.enums.operation"
            },
            "visible": "always"
          },
          {
            "path": "@.to",
            "label": "From Safe",
            "format": "addressName",
            "params": {
              "types": [
                "contract"
              ]
            }
          },
          {
            "path": "@.from",
            "label": "Execution signer",
            "format": "addressName",
            "params": {
              "types": [
                "eoa"
              ]
            }
          },
          {
            "path": "to",
            "label": "To",
            "format": "addressName",
            "params": {
              "types": [
                "eoa",
                "wallet",
                "contract"
              ]
            },
            "visible": "always"
          },
          {
            "path": "value",
            "label": "Amount",
            "format": "amount",
            "visible": "always"
          },
          {
            "path": "@.value",
            "label": "Value sent",
            "format": "amount",
            "visible": { "ifNotIn": [0, "0"] }
          },
          {
            "path": "data",
            "label": "Transaction",
            "format": "calldata",
            "params": {
              "calleePath": "to",
              "amountPath": "value",
              "spenderPath": "@.to"
            },
            "visible": "always"
          },
          {
            "path": "baseGas",
            "label": "Gas amount",
            "format": "raw",
            "visible": "always"
          },
          {
            "path": "gasPrice",
            "label": "Gas price",
            "format": "tokenAmount",
            "params": {
              "tokenPath": "gasToken",
              "nativeCurrencyAddress": "$.metadata.constants.addressAsNull"
            },
            "visible": "always"
          },
          {
            "path": "refundReceiver",
            "label": "Gas receiver",
            "format": "addressName",
            "params": {
              "types": [
                "eoa",
                "wallet",
                "contract"
              ]
            },
            "visible": "always"
          },
          {
            "label": "Safe Tx Gas",
            "path": "safeTxGas",
            "visible": "never"
          },
          {
            "label": "Signatures",
            "path": "signatures",
            "visible": "never"
          }
        ]
      },
      "addOwnerWithThreshold(address owner, uint256 _threshold)": {
        "$id": "addOwnerWithThreshold",
