              "types": [
                "eoa"
              ]
            },
            "visible": "always"
          },
          {
            "path": "newOwner",
            "label": "New signer",
            "format": "addressName",
            "params": {
              "types": [
                "eoa"
              ]
            },
            "visible": "always"
          },
          {
            "label": "Prev Owner",
            "path": "prevOwner",
            "visible": "never"
          }
        ]
      },
      "changeThreshold(uint256 _threshold)": {
        "$id": "changeThreshold",
